@startuml

abstract class Employee {
  + ssNo : int
  + name : string
  + email : string
}

class AdministrativeEmployee extends Employee {}

class ResearchAssistant extends Employee {
  + fieldOfStudy : string
}

class Lecturer extends ResearchAssistant {}

class Faculty {
  + name : string
}

class Institute {
  + name : string
  + address : string
}

class Project {
  + name : string
  + startDate : date
  + endDate : date
}

class Participation {
  + hours : int
}

class Course {
  + id : int
  + name : string
  + weeklyDuration : int
}

Faculty "1" *-- "1..*" Institute
Faculty "1" -- "0..1" Employee : headed by dean
Institute "1..*" -- "1..*" ResearchAssistant : assigned to
ResearchAssistant "1" -- "0..*" Participation : involved in
Participation "*" -- "1" Project
Lecturer "0..*" -- "1..*" Course : teaches

@enduml

